    imageUrl: "https://images.unsplash.com/photo-1452421822248-d4c2b47f0c81?w=1600&q=80",
    imageAlt: "Паспорт и документы — авторизация ETIAS для безвизовых путешественников в ЕС",
    author: "Zespół getpermit.pl",
